/// Decode-then-encode by type name. Used only by the shared conformance runner.
pub fn conformance_round_trip(type_name: &str, value: &Value) -> Option<Result<Value, DecodeError>> {
    match type_name {
        "ConnectionId" => Some(decode_connection_id(value, "$").map(|decoded| encode_connection_id(&decoded))),
        "PeerStaleReason" => Some(decode_peer_stale_reason(value, "$").map(|decoded| encode_peer_stale_reason(&decoded))),
        "SdpType" => Some(decode_sdp_type(value, "$").map(|decoded| encode_sdp_type(&decoded))),
        "SessionDescription" => Some(decode_session_description(value, "$").map(|decoded| encode_session_description(&decoded))),
        "IceCandidate" => Some(decode_ice_candidate(value, "$").map(|decoded| encode_ice_candidate(&decoded))),
        "IceServer" => Some(decode_ice_server(value, "$").map(|decoded| encode_ice_server(&decoded))),
        "PeerState" => Some(decode_peer_state(value, "$").map(|decoded| encode_peer_state(&decoded))),
        "RemoteKind" => Some(decode_remote_kind(value, "$").map(|decoded| encode_remote_kind(&decoded))),
        "RemoteTarget" => Some(decode_remote_target(value, "$").map(|decoded| encode_remote_target(&decoded))),
        "PeerRequest" => Some(decode_peer_request(value, "$").map(|decoded| encode_peer_request(&decoded))),
        "PeerResult" => Some(decode_peer_result(value, "$").map(|decoded| encode_peer_result(&decoded))),
        "PeerFact" => Some(decode_peer_fact(value, "$").map(|decoded| encode_peer_fact(&decoded))),
        _ => None,
    }
}
